insert into public.policy_documents(doc_type, role, version, title, effective_date, sections) values ('terms','client','1.0','Client Terms of Service','2026-11-01','[{"h": "1. About TSKR", "p": "TSKR is an online marketplace that connects you with independent service providers (taskers). TSKR does not perform the services itself. Taskers are not TSKR employees."}, {"h": "2. Your account", "p": "You must be at least 18 years old. You sign up with a verified email and a mobile number confirmed by a one-time code. One person, one account."}, {"h": "3. Your name", "p": "Use your real name, exactly as it appears on a valid government ID. When your tasker arrives, they may ask to see your ID to confirm the booking."}, {"h": "4. Bookings and prices", "p": "Your tasker sends an initial offer in chat. After seeing the actual work on site, the tasker confirms a final price, which you may accept or decline. Declining the final price cancels the booking at no charge."}, {"h": "5. Payment", "p": "You pay your tasker directly, in cash or by scanning their payment QR, which you see after accepting their offer. TSKR does not collect or hold payment for services."}, {"h": "6. Cancellations", "p": "Cancelling is free before your tasker leaves. After that, one late cancellation per month is free; later ones carry a ₱100 fee, paid straight to that tasker’s payment QR before your next booking. It is always free if your tasker is 15+ minutes late, cannot be reached, or asks to deal outside TSKR."}, {"h": "7. Free plan and TSKR Plus", "p": "Free accounts can book 1 service per day, for now only. TSKR Plus lets you book up to 5 services at once and schedule for later, for a monthly fee. You can cancel TSKR Plus anytime."}, {"h": "8. Deliveries", "p": "You enter the pickup (FROM) and drop-off (TO) addresses when you book. Items must fit a motorcycle top box or compartment. You may not send people, animals, hazardous or PDEA-regulated chemicals, drugs or medicines, alcohol, cigarettes or vapes, poison, illegal items or weapons. Your tasker may open and check your items before starting."}, {"h": "9. Safety and conduct", "p": "Be respectful and keep chats, calls and photos in the app. Personal services such as massage, escort, companion, model or hostess services are not allowed. Use SOS or Report if anything feels unsafe."}, {"h": "10. Reviews", "p": "Ratings and reviews only count for bookings made in TSKR and must be honest. Taskers also rate clients."}, {"h": "11. Deactivating or deleting your account", "p": "You may deactivate or delete your account in the app after giving a reason, once you have no active booking and no unpaid fee. Records of your bookings, payments, chats and reports are kept as stated in the Privacy Policy, and come back if you sign up again."}, {"h": "12. Suspension and liability", "p": "We may suspend accounts that break these Terms or move bookings outside TSKR. Taskers are responsible for their work; to the extent allowed by law, TSKR is not liable for losses caused by a tasker. Raise disputes in the Help center."}, {"h": "13. Changes and governing law", "p": "We will ask you to accept major changes. These Terms are governed by the laws of the Republic of the Philippines."}]'::jsonb) on conflict do nothing;
insert into public.policy_documents(doc_type, role, version, title, effective_date, sections) values ('privacy','client','1.0','Client Privacy Policy','2026-11-01','[{"h": "1. Who we are", "p": "TSKR is the personal information controller for data collected through the app. You can reach our Data Protection Officer through the Help center."}, {"h": "2. What we collect", "p": "Your name, email and mobile number; addresses you save; chats, offers, photos and reviews; and booking and payment records. We do not collect a profile photo, government ID or selfie from clients."}, {"h": "3. Location", "p": "We use your location only during an active booking, to show the live map, ETA and safety features. We do not track you outside bookings."}, {"h": "4. Why we use it", "p": "To create and verify your account, match you with taskers, run bookings, keep users safe, prevent fraud, handle support and disputes, and meet legal duties."}, {"h": "5. Who we share it with", "p": "Your tasker sees your masked name, then your full name and booking address after you accept an offer. We also share data with service providers that help us run TSKR (cloud hosting, SMS, payments) and with authorities when the law requires."}, {"h": "6. How long we keep it", "p": "While your account is active, and for 5 years after you deactivate or delete it: your account details, bookings, payment references, chats, reports and the reason you gave for leaving. We keep these only for disputes, fraud and safety investigations, and lawful requests from authorities."}, {"h": "7. Your rights", "p": "Under the Data Privacy Act of 2012, you may access, correct and download your data, deactivate or delete your account (records are kept as in item 6), object to processing and withdraw consent, in Account › Legal and privacy. You may also complain to the National Privacy Commission."}, {"h": "8. Security and changes", "p": "We encrypt sensitive data and limit staff access. We will tell you about important changes and ask for consent again when required."}]'::jsonb) on conflict do nothing;
insert into public.policy_documents(doc_type, role, version, title, effective_date, sections) values ('terms','tasker','1.0','Tasker Terms of Service','2026-11-01','[{"h": "1. Your relationship with TSKR", "p": "You are an independent contractor, not an employee or agent of TSKR. You set your own prices, choose which jobs to accept and decide your own hours."}, {"h": "2. Verification", "p": "To receive bookings you must pass identity verification: 2 valid government IDs and a selfie face check. The name on your account must match your IDs. We may re-verify you at any time."}, {"h": "3. Skills and licenses", "p": "Your first 2 skills are free. You may add up to 3 more (5 in total) for 100 coins per extra skill each week. Skills that need a license (for example medical, legal or electrical work) require proof of that license. Personal services such as massage, escort, companion, model or hostess services are prohibited."}, {"h": "4. Coins and fees", "p": "You get 1,000 coins on sign-up and may buy more (1 coin = ₱1). A booking fee in coins is deducted only when you tap Start job. Extra skills are charged weekly in coins; if you lack coins, they are hidden until you buy more. Coins are non-refundable, cannot be converted to cash and cannot be transferred."}, {"h": "5. Prices and payment", "p": "You send an initial offer and confirm the final price on site. The client pays you directly, in cash or to the payment QR you upload. The QR’s account name must match your verified ID. TSKR does not hold your earnings. You are responsible for your own taxes."}, {"h": "6. Cancellations and strikes", "p": "Cancelling an accepted job without a valid reason earns a strike: 100 coins for the first, 200 coins and lower ranking for the second, and a 7-day pause for the third within 30 days. A no-show counts as 2 strikes."}, {"h": "7. Deliveries and driving", "p": "Deliveries are by motorcycle only and must fit your top box. You may open and check items before starting and decline prohibited ones. You may never carry people. As a driver for hire, you drive only the client’s own vehicle."}, {"h": "8. Safety and conduct", "p": "Go only to the booked address. You may ask the client to show an ID on arrival. Keep chats, calls and photos in the app. Use SOS or cancel with “I don’t feel safe” (no strike) if anything is wrong."}, {"h": "9. Reviews and portfolio", "p": "Ratings only count for bookings made in TSKR. Portfolio photos must be your own work, taken with the in-app camera."}, {"h": "10. Deactivating or deleting your account", "p": "You may deactivate or delete your account in the app after giving a reason, once you have no active job. Unused coins are not refunded. Your verification, coin, booking and strike records are kept as stated in the Privacy Policy, and come back if you sign up again."}, {"h": "11. Suspension and liability", "p": "We may suspend or remove accounts that break these Terms, receive serious reports, or move bookings outside TSKR. You are responsible for the quality and safety of your work and any damage you cause."}, {"h": "12. Changes and governing law", "p": "We will ask you to accept major changes. These Terms are governed by the laws of the Republic of the Philippines."}]'::jsonb) on conflict do nothing;
insert into public.policy_documents(doc_type, role, version, title, effective_date, sections) values ('privacy','tasker','1.0','Tasker Privacy Policy','2026-11-01','[{"h": "1. Who we are", "p": "TSKR is the personal information controller for data collected through the app. You can reach our Data Protection Officer through the Help center."}, {"h": "2. What we collect", "p": "Your name, email, mobile number and profile photo; photos of 2 government IDs, the details read from them, a selfie and a face-match result; your skills, prices, availability, portfolio photos, payment QR, coin and payment records, chats, reviews and strikes."}, {"h": "3. Location", "p": "We use your location only while you are online for a booking and during an active job, for the live map, ETA, arrival checks and safety. We do not track you outside bookings."}, {"h": "4. Why we use it", "p": "To verify your identity, show your profile to clients, match you with bookings, process coins and fees, keep users safe, prevent fraud, handle disputes and meet legal duties, including anti-money laundering rules."}, {"h": "5. Who sees it", "p": "Clients see your photo, masked name, skills, ratings and portfolio, then your full name after accepting your offer. Clients never see your IDs. Our verification team and ID-check provider see your IDs and selfie. We share data with payment partners and authorities when the law requires."}, {"h": "6. How long we keep it", "p": "While your account is active, and for 5 years after you deactivate or delete it: your ID checks, bookings, coin history, payment QR, chats, strikes, reports and the reason you gave for leaving. We keep these only for disputes, fraud and safety investigations, and lawful requests from authorities."}, {"h": "7. Your rights", "p": "Under the Data Privacy Act of 2012, you may access, correct and download your data, deactivate or delete your account (records are kept as in item 6), object to processing and withdraw consent, in Account › Legal and privacy. Withdrawing ID consent ends your tasker access. You may also complain to the National Privacy Commission."}, {"h": "8. Security and changes", "p": "We encrypt IDs and selfies, limit staff access and log who views verification records. We will tell you about important changes and ask for consent again when required."}]'::jsonb) on conflict do nothing;
insert into public.policy_documents(doc_type, role, version, title, effective_date, sections) values ('id_consent','tasker','1.0','Consent to ID and selfie processing','2026-11-01','[{"h": "What we collect", "p": "Photos of 2 different valid government IDs, the details read from them by OCR (name, date of birth, masked ID number, address), a selfie and a face-match result."}, {"h": "Why", "p": "To verify your identity and match your face to your IDs before you can receive bookings, and to meet anti-money laundering (AMLA) duties."}, {"h": "Who can access it", "p": "The TSKR verification team and our ID-check (KYC) provider. It may be shared with payment partners and authorities when the law requires. Clients never see your IDs."}, {"h": "How long we keep it", "p": "While your account is active and for at least 5 years after it is closed, then it is deleted by a scheduled job. Every staff view is logged."}, {"h": "Your choice", "p": "This consent is separate from the general Terms. You can withdraw it in Account › Legal and privacy; withdrawing ends your tasker access."}]'::jsonb) on conflict do nothing;
